import type { CSSObject } from '@emotion/react';
import emotionStyled from '@emotion/styled';

import { theme } from '../../../../theme';
import type { TextAlignment } from '../Heading';
import type {
  ParagraphColorType,
  ParagraphSize,
  ParagraphWeight,
} from './Paragraph';

interface StyledParagraphProps {
  $alignment: TextAlignment;
  $color?: string;
  $colortype: ParagraphColorType;
  $css?: CSSObject;
  $foreground: boolean;
  $selectable: boolean;
  $size: ParagraphSize;
  $weight: ParagraphWeight;
}

const paragraphSizeStyles: Record<ParagraphSize, CSSObject> = {
  basis: {
    fontSize: theme.fonts.fontSizes['3'],
    lineHeight: theme.fonts.lineHeights['6'],
  },
  small: {
    fontSize: theme.fonts.fontSizes['2'],
    lineHeight: theme.fonts.lineHeights['4'],
  },
  xsmall: {
    fontSize: theme.fonts.fontSizes['1'],
    lineHeight: theme.fonts.lineHeights['4'],
  },
};

const paragraphColors: Record<ParagraphColorType, string> = {
  primary: theme.colors.interfaceLabelPrimary,
  secondary: theme.colors.interfaceLabelSecondary,
  disabled: theme.colors.interfaceLabelDisabled,
  success: theme.colors.semanticSuccessText,
  error: theme.colors.semanticErrorText,
};

const foregroundParagraphColors: Record<ParagraphColorType, string> = {
  primary: theme.colors.interfaceForegroundLabelPrimary,
  secondary: theme.colors.interfaceForegroundLabelSecondary,
  disabled: theme.colors.interfaceForegroundLabelDisabled,
  success: theme.colors.semanticSuccessBasis,
  error: theme.colors.semanticErrorBasis,
};

const paragraphWeights: Record<ParagraphWeight, number> = {
  normal: theme.fonts.fontWeights.normal,
  medium: theme.fonts.fontWeights.medium,
  semibold: theme.fonts.fontWeights.semibold,
};

const resolveParagraphColor = (
  foreground: boolean,
  colortype: ParagraphColorType,
  color?: string,
) => {
  if (foreground) {
    return foregroundParagraphColors[colortype];
  }

  if (color === 'secondary' || color === 'text-secondary') {
    return paragraphColors.secondary;
  }

  return paragraphColors[colortype];
};

const getParagraphSelectionStyles = (
  selectable: boolean,
): CSSObject | undefined =>
  selectable
    ? {
        backgroundColor: 'rgb(from rgb(255, 255, 0) r g b / 40%)',
      }
    : undefined;

export const StyledParagraph = emotionStyled('p')<StyledParagraphProps>(
  ({
    $alignment,
    $color,
    $colortype,
    $css,
    $foreground,
    $selectable,
    $size,
    $weight,
  }) => ({
    color: resolveParagraphColor($foreground, $colortype, $color),
    fontFamily: theme.fonts.paragraph,
    fontWeight: paragraphWeights[$weight],
    margin: 0,
    textAlign: $alignment,
    userSelect: $selectable ? 'auto' : 'none',
    '&::selection': getParagraphSelectionStyles($selectable),
    ...paragraphSizeStyles[$size],
    ...$css,
  }),
);
